'use strict';
const workstreams=[
{name:'Design & alignment',icon:'map',tone:'purple',note:'Agree the foundation',tasks:[['Discovery',1,1,'Content inventory, access and MVP priorities.'],['Design',2,2,'Responsive layouts, editor trial and API contract draft.']]},
{name:'Website & member pages',icon:'layout',tone:'blue',note:'Frontend workstream',tasks:[['Public pages + CMS',3,4,'Astro templates, navigation and the editor publishing workflow.'],['Portal + microsites',5,6,'Member journeys and a reusable campaign template.'],['Integrate + complete',7,8,'Connect agreed real services and migrate priority content.'],['Fix + verify',9,10,'Resolve defects identified in end-to-end QA.']]},
{name:'Content & editors',icon:'edit',tone:'mint',note:'Publishing + migration',tasks:[['Inventory + trial',1,2,'Validate content scope and the CMS with editors.'],['Publishing pilot',3,4,'Content model, preview and a sample migration.'],['Priority migration',5,8,'Move the agreed content and verify resource permissions.'],['Training',11,11,'Editor walkthroughs and operational handover.']]},
{name:'Backend & connections',icon:'shield',tone:'purple',note:'Milestones to confirm',tasks:[['Agree connections',1,2,'Agree contracts and sequence with the backend owner.'],['Services · provisional',3,6,'Identity, permissions and CRM services: timing subject to backend confirmation.'],['Live integration',7,8,'Validate frontend-to-backend journeys and CRM mappings.'],['Security + failures',9,10,'Test authorization and integration failure behavior.'],['Operations',11,12,'Backups, monitoring and launch readiness.']]},
{name:'QA & release',icon:'devices',tone:'coral',note:'Formal validation: W09–12',tasks:[['Test + refine',9,10,'Check browsers, devices, keyboard journeys, permissions and CRM.'],['Accept + launch',11,12,'UAT, rollback rehearsal, controlled release and monitoring.']]},
{name:'SEO throughout',icon:'search',tone:'mint',note:'Architecture → launch',tasks:[['Structure + URLs',1,2,'Baseline, information architecture and URL / redirect strategy.'],['Build + migrate',3,8,'Metadata, links, structured data, redirects and performance.'],['Validate + monitor',9,12,'Crawl checks, production settings and launch search monitoring.']]}
];
const gates=[{week:2,label:'Blueprint agreed',icon:'map'},{week:4,label:'Publishing pilot',icon:'edit'},{week:8,label:'MVP candidate',icon:'layers'},{week:10,label:'QA reviewed',icon:'shield'},{week:12,label:'Launch gate',icon:'rocket'}];
function mountPlan(){const board=document.querySelector('#delivery-board');board.innerHTML='<div class="plan-shell"><div class="plan-top"><div><span class="plan-status-dot"></span><strong>Delivery workspace</strong><span class="plan-proposal">PROPOSED SEQUENCE</span></div><div class="plan-legend"><span class="legend-dev">Build</span><span class="legend-qa">Validate &amp; launch</span></div></div><div class="plan-intro"><span>'+icon('pointer')+' Select a week, work item or milestone to explore.</span><span class="plan-scroll-hint">Scroll horizontally on smaller screens ↔</span></div><div class="plan-scroll" tabindex="0" role="region" aria-label="12-week workstream map. Scroll horizontally to explore all weeks."><div class="plan-grid"><div class="plan-months"><span>WORKSTREAM</span><strong style="grid-column:2/6">01 / Establish the foundation</strong><strong style="grid-column:6/10">02 / Connect the platform</strong><strong class="qa" style="grid-column:10/14">03 / Validate &amp; launch</strong></div><div class="plan-weeks"><span class="plan-row-label">Planning week</span>'+weeks.map((w,i)=>'<button data-plan-week="'+i+'" aria-pressed="false" aria-label="Week '+(i+1)+': '+w.title+'"><small>W</small>'+String(i+1).padStart(2,'0')+'</button>').join('')+'</div>'+workstreams.map((lane,l)=>'<div class="plan-lane" data-lane="'+l+'"><div class="plan-label">'+icon(lane.icon)+'<span><strong>'+lane.name+'</strong><small>'+lane.note+'</small></span></div><div class="plan-bars">'+Array.from({length:12},(_,i)=>'<span class="plan-cell" data-cell-week="'+i+'" style="grid-column:'+(i+1)+'"></span>').join('')+lane.tasks.map(([title,start,end,detail],n)=>'<button class="plan-task '+lane.tone+'" data-task="'+l+':'+n+'" data-start="'+(start-1)+'" data-end="'+(end-1)+'" style="grid-column:'+start+'/'+(end+1)+'" aria-label="'+lane.name+': '+title+', weeks '+start+' to '+end+'" title="'+title+' · W'+start+'–'+end+'"><span>'+title+'</span></button>').join('')+'</div></div>').join('')+'<div class="plan-gates"><span class="plan-label">'+icon('check')+'<strong>Release checkpoints</strong></span><div>'+gates.map((g,i)=>'<button data-gate="'+i+'" style="grid-column:'+g.week+'" aria-label="Week '+g.week+' checkpoint: '+g.label+'">'+icon(g.icon)+'<span>'+g.label+'</span></button>').join('')+'</div></div></div></div><div class="plan-note">'+icon('shield')+'<p><strong>Backend timing is provisional.</strong> This map shows coordination needs, not a committed backend estimate. Confirm services and integration milestones with the backend owner.</p></div><div class="plan-mobile-week"><label for="plan-scrubber">Explore a week</label><input id="plan-scrubber" type="range" min="1" max="12" step="1" value="1"><output id="plan-scrubber-output" for="plan-scrubber">Week 01</output></div><div id="plan-selection" class="plan-selection" role="status" aria-live="polite">Week 01 selected · explore its work below.</div></div>';
board.querySelectorAll('[data-plan-week]').forEach((b,i)=>{b.onclick=()=>pickWeek(i);b.onkeydown=e=>{let next;if(e.key==='ArrowRight')next=Math.min(11,i+1);if(e.key==='ArrowLeft')next=Math.max(0,i-1);if(e.key==='Home')next=0;if(e.key==='End')next=11;if(next!==undefined){e.preventDefault();pickWeek(next);board.querySelector('[data-plan-week="'+next+'"]').focus()}}});board.querySelectorAll('[data-task]').forEach(b=>b.onclick=()=>{const [l,n]=b.dataset.task.split(':').map(Number),task=workstreams[l].tasks[n];pickWeek(Number(b.dataset.start),workstreams[l].name+' · '+task[0]+': '+task[3]);});board.querySelectorAll('[data-gate]').forEach(b=>b.onclick=()=>{const gate=gates[Number(b.dataset.gate)];pickWeek(gate.week-1,'Week '+gate.week+' checkpoint · '+gate.label+'. Acceptance is required before moving forward.');});document.querySelector('#plan-scrubber').oninput=e=>pickWeek(Number(e.target.value)-1);document.addEventListener('proposal-week',e=>syncPlan(e.detail));syncPlan(selectedWeek)}
function pickWeek(i,message){stopTour();setStage(Math.floor(i/2),i);if(message)document.querySelector('#plan-selection').textContent=message}
function syncPlan(i){document.querySelectorAll('[data-plan-week]').forEach(b=>b.setAttribute('aria-pressed',Number(b.dataset.planWeek)===i));document.querySelectorAll('[data-cell-week]').forEach(c=>c.classList.toggle('selected',Number(c.dataset.cellWeek)===i));document.querySelectorAll('[data-task]').forEach(b=>b.classList.toggle('active',i>=Number(b.dataset.start)&&i<=Number(b.dataset.end)));const input=document.querySelector('#plan-scrubber');if(input){input.value=i+1;input.setAttribute('aria-valuetext','Week '+(i+1)+': '+weeks[i].title);document.querySelector('#plan-scrubber-output').textContent='Week '+String(i+1).padStart(2,'0');document.querySelector('#plan-selection').textContent='Week '+String(i+1).padStart(2,'0')+' · '+weeks[i].title+'. Deliverables and SEO focus below.'}}
mountPlan();
const menuButton=document.querySelector('#nav-menu'),mobileMenu=document.querySelector('#mobile-menu');menuButton.onclick=()=>{const open=menuButton.getAttribute('aria-expanded')!=='true';menuButton.setAttribute('aria-expanded',open);menuButton.setAttribute('aria-label',open?'Close proposal menu':'Open proposal menu');mobileMenu.hidden=!open};document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!mobileMenu.hidden){mobileMenu.hidden=true;menuButton.setAttribute('aria-expanded','false');menuButton.setAttribute('aria-label','Open proposal menu');menuButton.focus()}});
document.querySelectorAll('a[href="#builder"]').forEach(a=>a.addEventListener('click',()=>{setCapability('cms');requestAnimationFrame(()=>document.querySelector('#builder').scrollIntoView({block:'start'}))}));mobileMenu.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{mobileMenu.hidden=true;menuButton.setAttribute('aria-expanded','false');menuButton.setAttribute('aria-label','Open proposal menu')}));
if('IntersectionObserver' in window){const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting)document.querySelectorAll('[data-nav]').forEach(a=>{if(a.dataset.nav===e.target.id)a.setAttribute('aria-current','location');else a.removeAttribute('aria-current')})}),{rootMargin:'-15% 0px -65% 0px'});['opportunity','platform','roadmap'].forEach(id=>observer.observe(document.getElementById(id)))}
